CREATE ROLE anon; CREATE ROLE authenticated;
CREATE SCHEMA auth; CREATE SCHEMA storage; CREATE SCHEMA extensions;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
GRANT USAGE ON SCHEMA public,auth,storage TO anon,authenticated;
CREATE TABLE profiles(id uuid primary key,role text,is_also_admin boolean);
CREATE TABLE teachers(id integer primary key,profile_id uuid,full_name text,staff_type text,positions text[],position text);
CREATE TABLE role_permissions(position text,feature text,allowed boolean);
CREATE TABLE events(id uuid primary key,status text,academic_year integer);
CREATE TABLE sports(id uuid primary key,event_id uuid,name text,gender text,education_level text,result_format text,sort_direction text);
CREATE TABLE students(id integer primary key,full_name text,main_room text);
CREATE TABLE team_colors(id uuid primary key,event_id uuid,name text,logo_url text);
CREATE TABLE registrations(id uuid primary key,event_id uuid,sport_id uuid,student_id integer,team_color_id uuid);
CREATE TABLE race_results(id uuid primary key,event_id uuid,sport_id uuid,student_id integer,team_color_id uuid,value numeric,round text);
CREATE TABLE medal_awards(id uuid primary key,event_id uuid,sport_id uuid,team_color_id uuid,medal_type text);
CREATE TABLE sports_gallery_photos(id uuid primary key default gen_random_uuid(),event_id uuid NOT NULL,sport_id uuid,team_color_id uuid,category text NOT NULL CHECK(category IN ('color','staff','judge')),custom_label text,caption text,photo_url text NOT NULL,uploaded_by uuid);
ALTER TABLE sports_gallery_photos ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE,DELETE ON sports_gallery_photos TO anon,authenticated;
CREATE POLICY existing_gallery ON sports_gallery_photos FOR ALL TO anon,authenticated USING(true) WITH CHECK(true);
CREATE TABLE storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text,name text);
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE,DELETE ON storage.objects TO anon,authenticated;
CREATE POLICY existing_storage ON storage.objects FOR ALL TO anon,authenticated USING(bucket_id='sports-gallery') WITH CHECK(bucket_id='sports-gallery');
